/*
 * Pro tips
 * - A set answers whether a value was already seen; counts are unnecessary.
 * - Return as soon as a repeated value appears.
 * - Check empty input, a singleton, and a duplicate far from its first occurrence.
 * - Complexity: O(n) expected time and O(u) space for u distinct values.
 */

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;
import java.util.stream.Collectors;

class Solution {
    public static boolean containsDuplicate(List<Integer> nums) {
        Set<Integer> seen = new HashSet<>();
        for (int num : nums) {
            if (seen.contains(num)) {
                return true;
            }
            seen.add(num);
        }
        return false;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> nums = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        boolean res = containsDuplicate(nums);
        System.out.println(res);
    }
}
